1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { loadPage, makeReply, flush } from './helpers/fake-dom.mjs';
4	
5	const APP = new URL('../public/app.js', import.meta.url).pathname;
6	const NO_REPLY = 'Could not reach the server.';
7	const FALLBACK = 'Request failed.';
8	const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];
9	
10	function bk(id, title, extra = {}) {
11	  return { id, room: 'Aurora', title, date: '2026-11-03', start: '09:00', end: '10:00', ...extra };
12	}
13	
14	async function setup({ bookings = [bk(1, 'one')], answerList = true } = {}) {
15	  const page = loadPage(APP);
16	  assert.equal(page.calls[0].url, '/api/rooms');
17	  page.calls[0].reply(makeReply(200, { rooms: ROOMS }));
18	  if (answerList) page.calls[1].reply(makeReply(200, { bookings }));
19	  await flush();
20	  return page;
21	}
22	
23	// The page runs in a separate vm realm, so copy values before deepEqual.
24	function plain(v) {
25	  return JSON.parse(JSON.stringify(v));
26	}
27	
28	function kids(els) {
29	  return [...els['booking-list'].children];
30	}
31	
32	function sameNodes(actual, expected, msg) {
33	  assert.equal(actual.length, expected.length, `${msg}: length`);
34	  expected.forEach((n, i) => assert.equal(actual[i], n, `${msg}: node ${i}`));
35	}
36	
37	function lineTexts(els) {
38	  return kids(els).map((li) => li.children[0].textContent);
39	}
40	
41	function fill(els, over = {}) {
42	  const v = { room: 'Cosmos', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...over };
43	  for (const k of Object.keys(v)) els[k].value = v[k];
44	}
45	
46	function submit(els) {
47	  return els['booking-form'].dispatch('submit');
48	}
49	
50	async function change(els, value) {
51	  els['filter-date'].value = value;
52	  els['filter-date'].dispatch('change');
53	}
54	
55	async function postPage(over) {
56	  const page = await setup();
57	  fill(page.els, over);
58	  submit(page.els);
59	  return { ...page, post: page.calls[2] };
60	}
