62	// 1. overlapping list fetches
63	async function threeFetches() {
64	  const page = await setup({ answerList: false });
65	  await change(page.els, 'a');
66	  await change(page.els, 'b');
67	  assert.equal(page.calls.length, 4);
68	  return page;
69	}
