71	test('overlapping fetches: earlier successes are ignored, last one wins', async () => {
72	  const { els, calls } = await threeFetches();
73	  const before = kids(els);
74	  calls[1].reply(makeReply(200, { bookings: [bk(1, 'A')] }));
75	  calls[2].reply(makeReply(200, { bookings: [bk(2, 'B')] }));
76	  await flush();
77	  sameNodes(kids(els), before, 'unchanged');
78	  assert.equal(els.error.textContent, '');
79	  calls[3].reply(makeReply(200, { bookings: [bk(3, 'C')] }));
80	  await flush();
81	  assert.deepEqual(lineTexts(els), ['2026-11-03 09:00-10:00 Aurora: C']);
82	});
