84	test('overlapping fetches: earlier 500 and failure after last success are ignored', async () => {
85	  const { els, calls } = await threeFetches();
86	  calls[3].reply(makeReply(200, { bookings: [bk(3, 'C')] }));
87	  await flush();
88	  const before = kids(els);
89	  calls[1].reply(makeReply(500, { error: 'boom' }));
90	  calls[2].fail();
91	  await flush();
92	  sameNodes(kids(els), before, 'unchanged');
93	  assert.equal(els.error.textContent, '');
94	  assert.deepEqual(lineTexts(els), ['2026-11-03 09:00-10:00 Aurora: C']);
95	});
