97	test('overlapping fetches: earlier bad json and 409 after last success are ignored', async () => {
98	  const { els, calls } = await threeFetches();
99	  calls[3].reply(makeReply(200, { bookings: [bk(3, 'C')] }));
100	  await flush();
101	  const before = kids(els);
