1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { loadPage, makeReply, flush } from './helpers/fake-dom.mjs';
4	
5	const APP = new URL('../public/app.js', import.meta.url).pathname;
6	const NO_REPLY = 'Could not reach the server.';
7	const FALLBACK = 'Request failed.';
8	const BOOKING = { id: 1, room: 'Aurora', title: 'one', date: '2026-11-03', start: '09:00', end: '10:00' };
9	
10	function booking(id, title) {
11	  return { ...BOOKING, id, title };
12	}
13	
14	async function withList(bookings = [BOOKING]) {
15	  const p = loadPage(APP);
16	  p.calls[1].reply(makeReply(200, { bookings }));
17	  await flush();
18	  return p;
19	}
20	
21	function listOf(els) {
22	  return [...els['booking-list'].children];
23	}
24	
25	function assertSameChildren(els, before) {
26	  const after = listOf(els);
27	  assert.equal(after.length, before.length);
28	  before.forEach((node, i) => assert.equal(after[i], node));
29	}
30	
31	async function refetchWith(settle) {
32	  const { els, calls } = await withList();
33	  const before = listOf(els);
34	  els['filter-date'].dispatch('change');
35	  settle(calls[2]);
36	  await flush();
37	  return { els, before };
38	}
